namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    public int Id { get; set; }
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
    public DateTime SubmittedAt { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    Department? GetDepartment(int id);
    List<Course> GetCourses(string? search = null, int? departmentId = null);
    Course? GetCourse(int id);
    List<Course> GetCoursesForDepartment(int departmentId);
    EnrollmentRequest SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();
    private int _nextEnrollmentId = 1;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language arts." },
            new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and their impact on civilization." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", DepartmentId = 1, InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT.", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Advanced study of data organization and algorithm design. Covers trees, graphs, sorting, and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:00-11:50 AM", DepartmentId = 1, InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm optimization and has published over 30 research papers.", IsFeatured = false },
            new() { Id = 3, Title = "Web Development", Code = "CS 320", Description = "Full-stack web development covering HTML, CSS, JavaScript, and server-side frameworks.", Credits = 3, Schedule = "Mon/Wed 2:00-3:20 PM", DepartmentId = 1, InstructorName = "Prof. Sarah Kim", InstructorBio = "Prof. Kim spent 10 years in the tech industry before joining academia. She specializes in modern web technologies.", IsFeatured = true },

            // Mathematics
            new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Introduction to differential calculus including limits, derivatives, and applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", DepartmentId = 2, InstructorName = "Dr. James Wilson", InstructorBio = "Dr. Wilson is an award-winning educator with a passion for making calculus accessible to all students.", IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", Description = "Study of vector spaces, linear transformations, matrices, and systems of equations.", Credits = 3, Schedule = "Tue/Thu 1:00-2:20 PM", DepartmentId = 2, InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez researches applied mathematics and has authored two textbooks on linear algebra.", IsFeatured = false },
            new() { Id = 6, Title = "Statistics", Code = "MATH 301", Description = "Probability theory, statistical inference, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00-11:50 AM", DepartmentId = 2, InstructorName = "Dr. David Park", InstructorBio = "Dr. Park brings real-world data science experience to the classroom with 8 years in industry.", IsFeatured = false },

            // English
            new() { Id = 7, Title = "Composition and Rhetoric", Code = "ENG 101", Description = "Develop essential writing skills including argumentation, research methods, and academic discourse.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", DepartmentId = 3, InstructorName = "Prof. Emily Davis", InstructorBio = "Prof. Davis is a published author and writing coach with expertise in academic and creative writing.", IsFeatured = false },
            new() { Id = 8, Title = "American Literature", Code = "ENG 250", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 2:00-3:20 PM", DepartmentId = 3, InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown specializes in 20th-century American fiction and has won multiple teaching awards.", IsFeatured = true },
            new() { Id = 9, Title = "Creative Writing", Code = "ENG 310", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction.", Credits = 3, Schedule = "Wed 6:00-8:50 PM", DepartmentId = 3, InstructorName = "Prof. Rachel Green", InstructorBio = "Prof. Green is an acclaimed novelist whose works have been translated into 12 languages.", IsFeatured = false },

            // Physics
            new() { Id = 10, Title = "General Physics I", Code = "PHYS 101", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00-1:50 PM + Lab Thu 2:00-4:50 PM", DepartmentId = 4, InstructorName = "Dr. Richard Feynman Jr.", InstructorBio = "Dr. Feynman brings enthusiasm and clarity to introductory physics with engaging demonstrations.", IsFeatured = false },
            new() { Id = 11, Title = "Electromagnetism", Code = "PHYS 202", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 10:00-11:50 AM", DepartmentId = 4, InstructorName = "Dr. Lisa Zhang", InstructorBio = "Dr. Zhang's research focuses on quantum electrodynamics and she holds patents in photonics.", IsFeatured = true },
            new() { Id = 12, Title = "Quantum Mechanics", Code = "PHYS 350", Description = "Introduction to quantum theory, wave functions, and the Schrödinger equation.", Credits = 3, Schedule = "Mon/Wed 3:00-4:20 PM", DepartmentId = 4, InstructorName = "Dr. Alan Quantum", InstructorBio = "Dr. Quantum has contributed to groundbreaking research in quantum computing.", IsFeatured = false },

            // History
            new() { Id = 13, Title = "World Civilizations", Code = "HIST 101", Description = "Survey of major world civilizations from ancient times to the modern era.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00-10:50 AM", DepartmentId = 5, InstructorName = "Dr. Patricia Stone", InstructorBio = "Dr. Stone is an archaeologist and historian who has led excavations on three continents.", IsFeatured = false },
            new() { Id = 14, Title = "Modern European History", Code = "HIST 220", Description = "European history from the Renaissance to the present day.", Credits = 3, Schedule = "Tue/Thu 11:00 AM-12:20 PM", DepartmentId = 5, InstructorName = "Dr. Thomas Reed", InstructorBio = "Dr. Reed is a specialist in modern European political history and diplomatic relations.", IsFeatured = true },
            new() { Id = 15, Title = "American Civil War", Code = "HIST 305", Description = "In-depth study of the causes, events, and aftermath of the American Civil War.", Credits = 3, Schedule = "Tue/Thu 3:30-4:50 PM", DepartmentId = 5, InstructorName = "Dr. Karen White", InstructorBio = "Dr. White has published extensively on Civil War-era social history.", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesForDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public EnrollmentRequest SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        request.Id = _nextEnrollmentId++;
        request.SubmittedAt = DateTime.UtcNow;
        _enrollments.Add(request);
        return request;
    }
}

