@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-section">
    <h1>University Course Catalog</h1>
    <p class="lead">Explore our diverse range of courses and find the perfect fit for your academic journey.</p>
</div>

<section class="featured-section">
    <h2>Featured Courses</h2>
    <div class="course-grid">
        @foreach (var course in featuredCourses)
        {
            var dept = departments.FirstOrDefault(d => d.Id == course.DepartmentId);
            <div class="course-card featured">
                <div class="card-badge">Featured</div>
                <h3>@course.Title</h3>
                <p class="course-code">@course.Code</p>
                <p class="course-meta">@course.Credits credits &bull; @dept?.Name</p>
                <p>@course.Description</p>
                <a href="/courses/@course.Id" class="btn-primary-link">View Details</a>
            </div>
        }
    </div>
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="dept-grid">
        @foreach (var dept in departments)
        {
            <a href="/departments/@dept.Id" class="dept-card">
                <h3>@dept.Name</h3>
                <p class="dept-code">@dept.Code</p>
            </a>
        }
    </div>
</section>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetCourses().Where(c => c.IsFeatured).ToList();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@rendermode InteractiveServer
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<div class="search-filters">
    <input type="text" @bind="searchText" @bind:event="oninput" placeholder="Search courses..." class="search-input" />
    <select @bind="selectedDepartment" class="filter-select">
        <option value="0">All Departments</option>
        @foreach (var dept in departments)
        {
            <option value="@dept.Id">@dept.Name</option>
        }
    </select>
</div>

<div class="course-grid">
    @foreach (var course in filteredCourses)
    {
        var dept = departments.FirstOrDefault(d => d.Id == course.DepartmentId);
        <div class="course-card">
            <h3>@course.Title</h3>
            <p class="course-code">@course.Code</p>
            <p class="course-meta">@course.Credits credits &bull; @dept?.Name</p>
            <a href="/courses/@course.Id" class="btn-primary-link">View Details</a>
        </div>
    }
</div>

@if (!filteredCourses.Any())
{
    <p class="no-results">No courses found matching your criteria.</p>
}

@code {
    private List<Department> departments = new();
    private List<Course> allCourses = new();
    private string searchText = string.Empty;
    private int selectedDepartment;

    private List<Course> filteredCourses => CatalogService.GetCourses(
        string.IsNullOrWhiteSpace(searchText) ? null : searchText,
        selectedDepartment > 0 ? selectedDepartment : null);

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        allCourses = CatalogService.GetCourses();
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course") - University Course Catalog</PageTitle>

@if (course is null)
{
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
}
else
{
    var dept = CatalogService.GetDepartment(course.DepartmentId);

    <nav class="breadcrumb-nav">
        <a href="/courses">Courses</a> &raquo;
        <a href="/departments/@dept?.Id">@dept?.Name</a> &raquo;
        <span>@course.Code</span>
    </nav>

    <div class="course-detail">
        <h1>@course.Title</h1>
        <p class="course-code">@course.Code</p>

        <div class="detail-grid">
            <div class="detail-main">
                <h2>Description</h2>
                <p>@course.Description</p>

                <h2>Schedule</h2>
                <p>@course.Schedule</p>

                <h2>Credits</h2>
                <p>@course.Credits</p>
            </div>

            <div class="detail-sidebar">
                <div class="instructor-card">
                    <h2>Instructor</h2>
                    <h3>@course.InstructorName</h3>
                    <p>@course.InstructorBio</p>
                </div>

                <a href="/enroll" class="btn-enroll">Enroll in This Course</a>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/departments"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Departments - University Course Catalog</PageTitle>

<h1>Departments</h1>

<div class="dept-list">
    @foreach (var dept in departments)
    {
        var courseCount = CatalogService.GetCoursesForDepartment(dept.Id).Count;
        <a href="/departments/@dept.Id" class="dept-card">
            <h2>@dept.Name</h2>
            <p class="dept-code">@dept.Code</p>
            <p>@dept.Description</p>
            <p class="course-count">@courseCount courses available</p>
        </a>
    }
</div>

@code {
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
    }
}

@page "/departments/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>@(department?.Name ?? "Department") - University Course Catalog</PageTitle>

@if (department is null)
{
    <h1>Department Not Found</h1>
    <p>The requested department could not be found.</p>
}
else
{
    <nav class="breadcrumb-nav">
        <a href="/departments">Departments</a> &raquo;
        <span>@department.Name</span>
    </nav>

    <h1>@department.Name</h1>
    <p class="dept-code">@department.Code</p>
    <p>@department.Description</p>

    <h2>Courses</h2>
    <div class="course-grid">
        @foreach (var course in courses)
        {
            <div class="course-card">
                <h3>@course.Title</h3>
                <p class="course-code">@course.Code</p>
                <p class="course-meta">@course.Credits credits</p>
                <a href="/courses/@course.Id" class="btn-primary-link">View Details</a>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Department? department;
    private List<Course> courses = new();

    protected override void OnInitialized()
    {
        department = CatalogService.GetDepartment(Id);
        if (department is not null)
            courses = CatalogService.GetCoursesForDepartment(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="confirmation-message">
        <h2>Enrollment Request Submitted!</h2>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request has been received and will be processed shortly.</p>
        <a href="/courses" class="btn-primary-link">Browse More Courses</a>
    </div>
}
else
{
    <p>Fill out the form below to submit an enrollment request.</p>

    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="EnrollForm" class="enroll-form">
        <div class="form-group">
            <label for="studentName">Student Name</label>
            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-control">
                <option value="0">-- Select a Course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.Code - @course.Title</option>
                }
            </InputSelect>
        </div>

        <button type="submit" class="btn-submit">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    private List<Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();
    }

    private void HandleSubmit()
    {
        if (!string.IsNullOrWhiteSpace(Model.StudentName) &&
            !string.IsNullOrWhiteSpace(Model.StudentId) &&
            Model.CourseId > 0)
        {
            CatalogService.SubmitEnrollmentRequest(Model);
            submitted = true;
        }
    }
}

